[ExtensionOf(formDataFieldStr(CustFreeInvoice, AVACustInvoiceLineAdjust, AVABonusAllocationBase))]
internal final class AVACustFreeInvoiceFrm_AVACustInvoiceLineAdjDS_AVABonusAllocationFld_Extension
